mapper.select:
SELECT og.goods_id as goods_id, og.goods_name as goods_name, SUM(og.number * og.price) as total_amount, SUM(og.number) as total_quantity, DATE(o.add_time) as order_date FROM dts_order_goods og INNER JOIN dts_order o ON og.order_id = o.id WHERE o.order_status IN
#{status}
AND DATE(o.add_time) >= #{startDate}
AND DATE(o.add_time) <= #{endDate}
AND og.goods_id = #{goodsId}
AND o.user_id = #{userId}
AND o.deleted = 0 GROUP BY og.goods_id, og.goods_name, DATE(o.add_time) ORDER BY order_date DESC, total_amount DESC

SELECT o.user_id as user_id, u.username as user_name, u.nickname as user_nick_name, SUM(og.number * og.price) as total_amount, SUM(og.number) as total_quantity, DATE(o.add_time) as order_date FROM dts_order_goods og INNER JOIN dts_order o ON og.order_id = o.id LEFT JOIN dts_user u ON o.user_id = u.id WHERE o.order_status IN
#{status}
AND DATE(o.add_time) >= #{startDate}
AND DATE(o.add_time) <= #{endDate}
AND og.goods_id = #{goodsId}
AND o.user_id = #{userId}
AND o.deleted = 0 GROUP BY o.user_id, u.username, u.nickname, DATE(o.add_time) ORDER BY order_date DESC, total_amount DESC

SELECT
    SUM(og.number * og.price) as total_amount,
    SUM(og.number) as total_quantity,
    DATE_FORMAT(o.add_time, '%Y-%m-01') as order_date
FROM dts_order_goods og
INNER JOIN dts_order o ON og.order_id = o.id
WHERE o.order_status IN

    #{status}


    AND DATE(o.add_time) >= #{startDate}


    AND DATE(o.add_time) <= #{endDate}


    AND og.goods_id = #{goodsId}


    AND o.user_id = #{userId}

AND o.deleted = 0
GROUP BY DATE_FORMAT(o.add_time, '%Y-%m')
ORDER BY order_date DESC
